"use client";
import React,{useEffect,useMemo,useState} from "react";
import {LayoutDashboard,MessageSquare,CalendarDays,Users,ChartNoAxesCombined,CreditCard,Sparkles,Bot,Megaphone,Workflow,PanelsTopLeft,GraduationCap,Folder,Star,ChartColumn,Settings,Search,Plus,ChevronDown,ChevronRight,ArrowUpRight,ArrowRight,ArrowLeft,Check,CheckCheck,X,MoreHorizontal,Download,Upload,ExternalLink,Mail,Phone,Globe,Target,Clock,CheckCircle2,Play,GripVertical,Trash2,Copy,Eye,Save,Menu,Bell,Command,Building2,Layers,Package,BookOpen,Filter,Send,FileText,RefreshCw,Link,ShieldCheck,ArrowDown,LogOut,Monitor,Smartphone,SquarePen,Image,Type,AlignLeft,MousePointerClick} from "./icons";
import {definitions,initial,tabs,settingsTabs,invoiceTotal,assessmentLines,validate,type Row,type Field} from "./model";
